-- 202611170720 · ENCENDIDO DEL SPRINT 2 (video) · CC1 · DECISIÓN Lenovo 17-nov 07:18 · Emilio FIRMÓ el encendido (encender no gasta)
-- Solo DATO en `oficina_tipos_de_grupo` video_mesa:
--   · `limites.video.plano_por_plano` true (camino B: un clip por plano, unidos) · `propuestas` 3 · `borrador.resolucion` 480p;
--   · los pasos del orden acordado: mesa → imagenes_clave (borrador) → borrador_video (tope US$ 20 las 3 propuestas) → aprobar_propuestas (espera al dueño · 2 rondas)
--     → imagenes_clave_final → revisar_imagenes_clave (de las finales) → pedido → video (15) → … (el resto igual).
--   El tope del encargo sigue en 45, el del video en 15 y la reserva en 30. `video_mesa` en `familias_activas` NO se toca (eso es el «dale» a la prueba de la semana).
-- Es el dato EXACTO de `VIDEO_MESA_ENCENDIDA` (src/lib/oficina/plantillas/video-mesa.ts · una prueba lo mantiene igual).
-- ORDEN: DESPUÉS de 202611170520 (las guardas exigen sus `limites` y los `pasos` de 202611162300 exactos). Se niega con encargos vivos.
-- Reversa: reversas/202611170720_oficina_video_encendido_sprint2_REVERSA.sql
BEGIN;

DO $$
BEGIN
  -- con CUALQUIER encargo vivo (real o ensayo) no se toca
  IF EXISTS (SELECT 1 FROM public.oficina_encargos WHERE estado IN ('abierto', 'en_paso')) THEN
    RAISE EXCEPTION '202611170720: hay encargos de la oficina vivos; esperar a que cierren';
  END IF;
  -- el dato de antes, ENTERO, es el esperado: si alguien lo cambió, no se pisa
  IF (SELECT limites FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM $lim_antes${"margen":50,"tope_encargo_usd":45,"max_rondas":2,"imagenes_generadas_max":0,"reuso_dias":14,"plataforma":"instagram-reel","pie_de_foto_max":2200,"hashtags_max":30,"limites_verificados":false,"formato_por_omision":"9:16","mesa":true,"video":{"resolucion":"720p","segundos_min":8,"segundos_max":15,"tope_por_video_usd":15},"reserva_por_pieza_usd":30,"imagen_clave":{"borrador":{"quality":"low","size":"1024x1536"},"final":{"quality":"max","size":"1024x1536"}}}$lim_antes$::jsonb THEN
    RAISE EXCEPTION '202611170720: los límites de video_mesa no son los esperados; no se pisan';
  END IF;
  IF (SELECT pasos FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM $pasos_antes$[{"clave":"abrir","tipo":"codigo","quien":"sala","funcion":"abrir_video","condicion":{"tipo":"siempre"},"entrada":[],"salida_artefacto":"encargo","tope_usd":0},{"clave":"mesa","tipo":"codigo","quien":"sala","funcion":"mesa","condicion":{"tipo":"siempre"},"entrada":["encargo"],"salida_artefacto":"mesa","tope_usd":0},{"clave":"imagenes_clave","tipo":"codigo","quien":"sala","funcion":"imagenes_clave","condicion":{"tipo":"siempre"},"entrada":["guion","encargo"],"salida_artefacto":"imagenes_clave","tope_usd":3},{"clave":"revisar_imagenes_clave","tipo":"agente","quien":"marketing_video_optimization_specialist","condicion":{"tipo":"si_artefacto","artefacto":"imagenes_clave","campo":"hay_imagenes","igual":true},"entrada":["imagenes_clave","guion"],"salida_artefacto":"revision_imagenes_clave","tope_usd":0.5,"salida":{"esquema":"revision_imagenes_clave.v1","reintento_formato":1},"vuelve_a":{"paso":"mesa","max":1,"si":{"tipo":"si_artefacto","artefacto":"revision_imagenes_clave","campo":"vuelve_a_la_mesa","igual":true}}},{"clave":"pedido","tipo":"codigo","quien":"sala","funcion":"pedido_de_video","condicion":{"tipo":"siempre"},"entrada":["guion","copy_video"],"salida_artefacto":"pedido_video","tope_usd":0,"vuelve_a":{"paso":"mesa","max":1,"si":{"tipo":"si_artefacto","artefacto":"pedido_video","campo":"vuelve_a_la_mesa","igual":true}}},{"clave":"video","tipo":"codigo","quien":"sala","funcion":"video","condicion":{"tipo":"siempre"},"entrada":["pedido_video"],"salida_artefacto":"video","tope_usd":15},{"clave":"cuadros_video","tipo":"codigo","quien":"sala","funcion":"cuadros_video","condicion":{"tipo":"siempre"},"entrada":["video","guion"],"salida_artefacto":"cuadros_video","tope_usd":0},{"clave":"mirar_video","tipo":"agente","quien":"marketing_video_optimization_specialist","condicion":{"tipo":"si_artefacto","artefacto":"cuadros_video","campo":"hay_cuadros","igual":true},"entrada":["cuadros_video","guion"],"salida_artefacto":"mirada_video","tope_usd":0.5,"salida":{"esquema":"mirada_video.v1","reintento_formato":1},"vuelve_a":{"paso":"mesa","max":1,"si":{"tipo":"si_artefacto","artefacto":"mirada_video","campo":"vuelve_a_la_mesa","igual":true}}},{"clave":"chequeos","tipo":"codigo","quien":"sala","funcion":"chequeos_video","condicion":{"tipo":"siempre"},"entrada":["video","copy_video","pedido_video"],"salida_artefacto":"chequeos","tope_usd":0},{"clave":"jefatura","tipo":"jefatura","quien":"jefatura","condicion":{"tipo":"siempre"},"entrada":["guion","copy_video","video","chequeos"],"salida_artefacto":"respuesta_imagen","tope_usd":0},{"clave":"chequeos_2","tipo":"codigo","quien":"sala","funcion":"chequeos_video","condicion":{"tipo":"si_cambio","artefacto":"copy_video"},"entrada":["video","copy_video","pedido_video"],"salida_artefacto":"chequeos","tope_usd":0},{"clave":"entrega","tipo":"codigo","quien":"sala","funcion":"empaquetar_entrega_video","condicion":{"tipo":"siempre"},"entrada":["copy_video","video","chequeos","guion"],"salida_artefacto":"entrega","tope_usd":0},{"clave":"cierre","tipo":"codigo","quien":"sala","funcion":"cierre","condicion":{"tipo":"siempre"},"entrada":["entrega"],"salida_artefacto":"cierre","tope_usd":0}]$pasos_antes$::jsonb THEN
    RAISE EXCEPTION '202611170720: los pasos de video_mesa no son los esperados; no se pisan';
  END IF;
  IF (SELECT tope_encargo_usd FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM 45::numeric THEN
    RAISE EXCEPTION '202611170720: el tope del encargo de video_mesa no es el esperado; no se pisa';
  END IF;
END $$;

UPDATE public.oficina_tipos_de_grupo SET pasos = $pasos$[{"clave":"abrir","tipo":"codigo","quien":"sala","funcion":"abrir_video","condicion":{"tipo":"siempre"},"entrada":[],"salida_artefacto":"encargo","tope_usd":0},{"clave":"mesa","tipo":"codigo","quien":"sala","funcion":"mesa","condicion":{"tipo":"siempre"},"entrada":["encargo"],"salida_artefacto":"mesa","tope_usd":0},{"clave":"imagenes_clave","tipo":"codigo","quien":"sala","funcion":"imagenes_clave","condicion":{"tipo":"siempre"},"entrada":["guion","encargo"],"salida_artefacto":"imagenes_clave","tope_usd":3},{"clave":"borrador_video","tipo":"codigo","quien":"sala","funcion":"borrador_video","condicion":{"tipo":"siempre"},"entrada":["imagenes_clave"],"salida_artefacto":"borrador_video","tope_usd":20},{"clave":"aprobar_propuestas","tipo":"codigo","quien":"sala","funcion":"aprobar_propuestas","condicion":{"tipo":"siempre"},"entrada":["mesa"],"salida_artefacto":"aprobacion_propuestas","tope_usd":0,"vuelve_a":{"paso":"mesa","max":2,"si":{"tipo":"si_artefacto","artefacto":"aprobacion_propuestas","campo":"vuelve_a_la_mesa","igual":true}}},{"clave":"imagenes_clave_final","tipo":"codigo","quien":"sala","funcion":"imagenes_clave","condicion":{"tipo":"siempre"},"entrada":["guion","encargo"],"salida_artefacto":"imagenes_clave_final","tope_usd":3},{"clave":"revisar_imagenes_clave","tipo":"agente","quien":"marketing_video_optimization_specialist","condicion":{"tipo":"si_artefacto","artefacto":"imagenes_clave_final","campo":"hay_imagenes","igual":true},"entrada":["imagenes_clave_final","guion"],"salida_artefacto":"revision_imagenes_clave","tope_usd":0.5,"salida":{"esquema":"revision_imagenes_clave.v1","reintento_formato":1},"vuelve_a":{"paso":"mesa","max":1,"si":{"tipo":"si_artefacto","artefacto":"revision_imagenes_clave","campo":"vuelve_a_la_mesa","igual":true}}},{"clave":"pedido","tipo":"codigo","quien":"sala","funcion":"pedido_de_video","condicion":{"tipo":"siempre"},"entrada":["guion","copy_video"],"salida_artefacto":"pedido_video","tope_usd":0,"vuelve_a":{"paso":"mesa","max":1,"si":{"tipo":"si_artefacto","artefacto":"pedido_video","campo":"vuelve_a_la_mesa","igual":true}}},{"clave":"video","tipo":"codigo","quien":"sala","funcion":"video","condicion":{"tipo":"siempre"},"entrada":["pedido_video"],"salida_artefacto":"video","tope_usd":15},{"clave":"cuadros_video","tipo":"codigo","quien":"sala","funcion":"cuadros_video","condicion":{"tipo":"siempre"},"entrada":["video","guion"],"salida_artefacto":"cuadros_video","tope_usd":0},{"clave":"mirar_video","tipo":"agente","quien":"marketing_video_optimization_specialist","condicion":{"tipo":"si_artefacto","artefacto":"cuadros_video","campo":"hay_cuadros","igual":true},"entrada":["cuadros_video","guion"],"salida_artefacto":"mirada_video","tope_usd":0.5,"salida":{"esquema":"mirada_video.v1","reintento_formato":1},"vuelve_a":{"paso":"mesa","max":1,"si":{"tipo":"si_artefacto","artefacto":"mirada_video","campo":"vuelve_a_la_mesa","igual":true}}},{"clave":"chequeos","tipo":"codigo","quien":"sala","funcion":"chequeos_video","condicion":{"tipo":"siempre"},"entrada":["video","copy_video","pedido_video"],"salida_artefacto":"chequeos","tope_usd":0},{"clave":"jefatura","tipo":"jefatura","quien":"jefatura","condicion":{"tipo":"siempre"},"entrada":["guion","copy_video","video","chequeos"],"salida_artefacto":"respuesta_imagen","tope_usd":0},{"clave":"chequeos_2","tipo":"codigo","quien":"sala","funcion":"chequeos_video","condicion":{"tipo":"si_cambio","artefacto":"copy_video"},"entrada":["video","copy_video","pedido_video"],"salida_artefacto":"chequeos","tope_usd":0},{"clave":"entrega","tipo":"codigo","quien":"sala","funcion":"empaquetar_entrega_video","condicion":{"tipo":"siempre"},"entrada":["copy_video","video","chequeos","guion"],"salida_artefacto":"entrega","tope_usd":0},{"clave":"cierre","tipo":"codigo","quien":"sala","funcion":"cierre","condicion":{"tipo":"siempre"},"entrada":["entrega"],"salida_artefacto":"cierre","tope_usd":0}]$pasos$::jsonb, limites = $lim${"margen":50,"tope_encargo_usd":45,"max_rondas":2,"imagenes_generadas_max":0,"reuso_dias":14,"plataforma":"instagram-reel","pie_de_foto_max":2200,"hashtags_max":30,"limites_verificados":false,"formato_por_omision":"9:16","mesa":true,"video":{"resolucion":"720p","segundos_min":8,"segundos_max":15,"tope_por_video_usd":15,"plano_por_plano":true,"propuestas":3,"borrador":{"resolucion":"480p"}},"reserva_por_pieza_usd":30,"imagen_clave":{"borrador":{"quality":"low","size":"1024x1536"},"final":{"quality":"max","size":"1024x1536"}}}$lim$::jsonb WHERE familia = 'video_mesa';

DO $$
BEGIN
  IF (SELECT limites->'video'->>'plano_por_plano' FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM 'true'
     OR (SELECT EXISTS (SELECT 1 FROM jsonb_array_elements(pasos) p WHERE p->>'clave' = 'aprobar_propuestas') FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM true
     OR (SELECT tope_encargo_usd FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM 45::numeric THEN
    RAISE EXCEPTION '202611170720: video_mesa no quedó encendida';
  END IF;
END $$;

COMMIT;
